application.css:
* {
  box-sizing: border-box;
}

:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #20253d;
  background: #f5f7ff;
}

body {
  margin: 0;
  min-height: 100vh;
  background: radial-gradient(circle at 12% 10%, #e4e9ff 0, transparent 35%), radial-gradient(circle at 90% 90%, #dff7f0 0, transparent 34%), #f7f8fc;
}

.app-shell {
  width: min(100% - 32px, 660px);
  margin: 0 auto;
  padding: 70px 0 30px;
}

.todo-card {
  overflow: hidden;
  background: rgba(255, 255, 255, .94);
  border: 1px solid #e7eaf4;
  border-radius: 24px;
  box-shadow: 0 20px 60px rgba(50, 62, 111, .12);
}

.hero {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 34px 36px 29px;
  background: linear-gradient(120deg, #5965d8, #7665d9);
  color: white;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  border: 1px solid rgba(255,255,255,.35);
  border-radius: 16px;
  background: rgba(255,255,255,.16);
  font-size: 27px;
  font-weight: 700;
}

.eyebrow {
  margin: 0 0 4px;
  color: #d9dcff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 3px; font-size: 30px; letter-spacing: -.8px; }
.subtitle { margin: 0; color: #e4e5ff; font-size: 14px; }

.task-form {
  display: flex;
  gap: 10px;
  padding: 27px 36px 0;
}

.task-form input {
  min-width: 0;
  flex: 1;
  padding: 14px 16px;
  border: 1px solid #dfe3ef;
  border-radius: 12px;
  outline: none;
  color: #20253d;
  background: #fafbfe;
  font: inherit;
  transition: border .2s, box-shadow .2s;
}

.task-form input:focus { border-color: #6871db; box-shadow: 0 0 0 4px rgba(104,113,219,.13); }
.task-form button {
  border: 0;
  border-radius: 12px;
  padding: 0 18px;
  color: white;
  background: #5965d8;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  transition: transform .15s, background .15s;
}
.task-form button:hover { background: #4855c8; transform: translateY(-1px); }
.task-form button span { margin-left: 5px; font-size: 18px; vertical-align: -1px; }

.form-message { min-height: 18px; margin: 7px 36px 0; color: #d05267; font-size: 12px; }
.list-heading { display: flex; align-items: center; justify-content: space-between; padding: 18px 36px 13px; }
h2 { margin: 0; font-size: 16px; }
.count-pill { padding: 6px 10px; border-radius: 20px; color: #5965c9; background: #eef0ff; font-size: 12px; font-weight: 700; }

.task-list { padding: 0 36px 28px; }
.task {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 4px;
  border-top: 1px solid #edf0f6;
  animation: appear .2s ease-out;
}
.task-text { flex: 1; overflow-wrap: anywhere; font-size: 15px; line-height: 1.4; }
.task[data-completed="true"] .task-text { color: #9aa0b1; text-decoration: line-through; }
.complete-control {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  flex: 0 0 22px;
  border: 2px solid #cbd0e2;
  border-radius: 7px;
  color: white;
  background: transparent;
  cursor: pointer;
}
.task[data-completed="true"] .complete-control { border-color: #5965d8; background: #5965d8; }
.complete-control::after { content: "✓"; opacity: 0; font-size: 13px; font-weight: 800; }
.task[data-completed="true"] .complete-control::after { opacity: 1; }
.delete-control { border: 0; color: #a8adbd; background: none; font-size: 20px; line-height: 1; cursor: pointer; }
.delete-control:hover { color: #d05267; }
.empty-state { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 18px 20px 36px; color: #9ba1b2; font-size: 13px; }
.empty-state strong { color: #646b80; font-size: 14px; }
.empty-icon { display: grid; place-items: center; width: 40px; height: 40px; margin-bottom: 3px; border-radius: 50%; color: #7d86e2; background: #eef0ff; font-size: 20px; }
.footer-note { margin: 18px 0 0; color: #9da4b8; text-align: center; font-size: 12px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 520px) { .app-shell { padding-top: 24px; } .hero, .task-form, .list-heading { padding-left: 22px; padding-right: 22px; } .task-list { padding-left: 22px; padding-right: 22px; } .task-form { flex-direction: column; } .task-form button { padding: 13px; } .form-message { margin-left: 22px; margin-right: 22px; } }

application.javascript:
(() => {
  const form = document.getElementById('task-form');
  const input = document.querySelector('[data-testid="task-input"]');
  const list = document.querySelector('[data-testid="task-list"]');
  const count = document.querySelector('[data-testid="incomplete-count"]');
  const empty = document.getElementById('empty-state');
  const message = document.getElementById('form-message');
  let tasks = [];

  function render() {
    list.replaceChildren();
    tasks.forEach(task => {
      const item = document.createElement('div');
      item.className = 'task';
      item.dataset.testid = 'task';
      item.dataset.completed = String(task.completed);

      const toggle = document.createElement('button');
      toggle.type = 'button';
      toggle.className = 'complete-control';
      toggle.dataset.testid = 'task-complete';
      toggle.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
      toggle.addEventListener('click', () => {
        task.completed = !task.completed;
        render();
      });

      const text = document.createElement('span');
      text.className = 'task-text';
      text.dataset.testid = 'task-text';
      text.textContent = task.text;

      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'delete-control';
      remove.dataset.testid = 'task-delete';
      remove.setAttribute('aria-label', `Delete ${task.text}`);
      remove.textContent = '×';
      remove.addEventListener('click', () => {
        tasks = tasks.filter(current => current !== task);
        render();
      });

      item.append(toggle, text, remove);
      list.appendChild(item);
    });
    count.textContent = tasks.filter(task => !task.completed).length;
    empty.hidden = tasks.length > 0;
  }

  form.addEventListener('submit', event => {
    event.preventDefault();
    const value = input.value.trim();
    if (!value) {
      message.textContent = 'Please enter a task first.';
      input.focus();
      return;
    }
    tasks.push({ text: value, completed: false });
    input.value = '';
    message.textContent = '';
    render();
    input.focus();
  });

  input.addEventListener('input', () => { if (input.value.trim()) message.textContent = ''; });
  render();
})();

